patch_result.patch:
--- a/src/sksl/ir/SkSLVariableReference.cpp
+++ b/src/sksl/ir/SkSLVariableReference.cpp
@@ -53,11 +53,14 @@
     if (this->refKind() != RefKind::kRead) {
         return nullptr;
     }
-    const Expression* initialValue = this->variable()->initialValue();
-    if ((this->variable()->modifiers().fFlags & Modifiers::kConst_Flag) && initialValue &&
-        initialValue->isCompileTimeConstant() &&
-        !this->type().isArray()) {
-        return initialValue->clone();
+    if ((this->variable()->modifiers().fFlags & Modifiers::kConst_Flag) && !this->type().isArray()) {
+        // Const variables should always have a known definition; relying on the declaration's
+        // initializer can be unsafe after CFG/IR rewrites.
+        if (Expression* expr = definitions.getKnownDefinition(this->variable())) {
+            if (expr->isCompileTimeConstant()) {
+                return expr->clone();
+            }
+        }
     }
     Expression* expr = definitions.getKnownDefinition(this->variable());
     return expr ? expr->clone() : nullptr;

args:
@@ -53,11 +53,14 @@ std::unique_ptr<Expression> VariableReference::constantPropagate(const IRGenerat
     if (this->refKind() != RefKind::kRead) {
         return nullptr;
     }
-    const Expression* initialValue = this->variable()->initialValue();
-    if ((this->variable()->modifiers().fFlags & Modifiers::kConst_Flag) && initialValue &&
-        initialValue->isCompileTimeConstant() &&
-        !this->type().isArray()) {
-        return initialValue->clone();
+    if ((this->variable()->modifiers().fFlags & Modifiers::kConst_Flag) && !this->type().isArray()) {
+        // Const variables should always have a known definition; relying on the declaration's
+        // initializer can be unsafe after CFG/IR rewrites.
+        if (Expression* expr = definitions.getKnownDefinition(this->variable())) {
+            if (expr->isCompileTimeConstant()) {
+                return expr->clone();
+            }
+        }
     }
     Expression* expr = definitions.getKnownDefinition(this->variable());
     return expr ? expr->clone() : nullptr;
